class Solution {
  public int minimumMoves(int[] arr) {
    int n = arr.length;
    int[][] dp = new int[n + 1][n + 1]; // dp[i][j]: fewest moves to clear arr[i..j]
    for (int i = n - 1; i >= 0; i--) {
      for (int j = i; j < n; j++) {
        dp[i][j] = 1 + (i + 1 <= j ? dp[i + 1][j] : 0); // remove arr[i] on its own
        // or remove arr[i] together with a matching arr[k], as the outer ends of a palindrome
        for (int k = i + 1; k <= j; k++) {
          if (arr[i] != arr[k]) continue;
          int inner = k == i + 1 ? 1 : dp[i + 1][k - 1];
          int rest = k + 1 <= j ? dp[k + 1][j] : 0;
          dp[i][j] = Math.min(dp[i][j], inner + rest);
        }
      }
    }
    return dp[0][n - 1];
  }
}
